#if APP_TESTS
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace FileCompass {
 internal static class MediaEditorTests {
  static void CheckLayout(MediaEditorWindow editor,Action<bool,string> check,string category){editor.Width=900;editor.Height=600;editor.UpdateLayout();var grid=editor.EditorGrid;check(!grid.Children.OfType<System.Windows.Controls.ScrollViewer>().Any(),category+" editor fields have no scroll container");foreach(var box in editor.Fields.Values.Where(x=>x.IsVisible)){var end=box.TranslatePoint(new System.Windows.Point(box.ActualWidth,box.ActualHeight),grid);check(box.ActualWidth>=65&&end.X<=grid.ActualWidth+.5&&end.Y<=grid.ActualHeight+.5,category+" field fits without clipping: "+box.Tag);}check(editor.List.ActualHeight>=70,category+" file list retains usable space at 900x600");check(editor.Mask.ActualWidth>=55,category+" filename mask remains editable at 900x600");if(category=="Music"){string original=editor.Mask.Text;editor.Mask.Text="aXXb";editor.Mask.Select(1,2);var button=FluentUiTests.Children<System.Windows.Controls.Button>(editor).Single(x=>Convert.ToString(x.Content)==L.Text("rename.insertToken"));button.RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));var menu=(System.Windows.Controls.ContextMenu)editor.Mask.GetValue(TokenDropdown.MenuProperty);var items=menu.Items.Cast<System.Windows.Controls.MenuItem>().ToArray();check(menu.IsOpen&&MediaNames.WritableTokens.Concat(new[]{"[Ignore]"}).All(t=>items.Any(x=>Convert.ToString(x.Tag)==t)),"Editor button opens every writable filename token");items.Single(x=>Convert.ToString(x.Tag)=="[MP3.AlbumArtist]").RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.MenuItem.ClickEvent));check(editor.Mask.Text=="a[MP3.AlbumArtist]b","Editor token replaces the selected mask text");menu.IsOpen=false;editor.Mask.Text=original;}}
  internal static void Run(string root,Action<bool,string> check){
   Directory.CreateDirectory(root);string first=Path.Combine(root,"Artist - 01 - Title.mp3"),second=Path.Combine(root,"second.mp3"),image=Path.Combine(root,"photo.png");
   foreach(string path in new[]{first,second})using(var output=File.Create(path))for(int i=0;i<12;i++){var frame=new byte[417];frame[0]=255;frame[1]=251;frame[2]=144;frame[3]=100;output.Write(frame,0,frame.Length);}
   var bitmap=BitmapSource.Create(8,8,96,96,PixelFormats.Rgb24,null,new byte[192],24);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(image))png.Save(output);
   var manual=MediaNames.PreviewValues(first,new Dictionary<string,string>{{"[MP3.AlbumArtist]","Album artist"},{"[MP3.Comment]","Edited"},{"[MP3.TrackCount]","12"},{"[MP3.Year]","2020"}},true,CancellationToken.None);check(manual.Changes!=null&&manual.Changes.Count==4,"Manual audio changes are prepared and validated");byte[] cover=File.ReadAllBytes(image);manual.CoverChanged=true;manual.Cover=cover;manual.CoverMime="image/png";MediaNames.Apply(manual,CancellationToken.None);using(var file=TagLib.File.Create(first)){check(file.Tag.AlbumArtists.Single()=="Album artist"&&file.Tag.Comment=="Edited"&&file.Tag.TrackCount==12,"Manual audio fields are written and verified");check(file.Tag.Pictures.Any(x=>x.Type==TagLib.PictureType.FrontCover&&x.Data.Data.SequenceEqual(cover)),"Front cover is embedded without changing its bytes");}
   var rename=BatchRenameEngine.Preview(new[]{first},new RenameOptions{Name="[MP3.AlbumArtist]_[MP3.TrackCount]_[MP3.Comment]"})[0];check(rename.NewName=="Album artist_12_Edited.mp3","New music metadata tokens produce filenames");var parsed=MediaNames.Parse("003 - Artist","[MP3.TrackCount] - [MP3.AlbumArtist]");check(parsed["[MP3.TrackCount]"]=="3"&&parsed["[MP3.AlbumArtist]"]=="Artist","New editable tokens also parse filename masks");
   var clear=MediaNames.PreviewValues(first,new Dictionary<string,string>{{"[MP3.Comment]",""},{"[MP3.TrackCount]",""}},true,CancellationToken.None);clear.CoverChanged=true;MediaNames.Apply(clear,CancellationToken.None);using(var file=TagLib.File.Create(first))check(String.IsNullOrEmpty(file.Tag.Comment)&&file.Tag.TrackCount==0&&!file.Tag.Pictures.Any(x=>x.Type==TagLib.PictureType.FrontCover),"Explicit clearing removes selected fields and cover");
   var edit=MediaNames.PreviewValues(image,new Dictionary<string,string>{{"[Image.Author]","Autor"},{"[Image.Copyright]","Copyright"}},true,CancellationToken.None);MediaNames.Apply(edit,CancellationToken.None);using(var file=TagLib.File.Create(image)){var tag=(TagLib.Image.CombinedImageTag)file.Tag;check(tag.Creator=="Autor"&&tag.Copyright=="Copyright","Manual image fields roundtrip");}
   var editor=new MediaEditorWindow(null,new[]{first,second,image},()=>{},v=>{},null,null){Left=-18000,Top=-18000};editor.Show();NavigationTests.Wait(editor.Work);check(editor.List.Items.Count==2,"Mixed selection separates music from images");CheckLayout(editor,check,"Music");NextStageTests.Draw(editor,Path.Combine(root,"metadata-editor-music.png"));var parse=FluentUiTests.Children<System.Windows.Controls.Button>(editor).Single(x=>Convert.ToString(x.Content)==L.Text("mediaEditor.fromName"));parse.RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));check(((MediaEditorRow)editor.List.Items[0]).Value("[MP3.Title]")=="Title","Filename parsing updates the selected draft");editor.List.SelectAll();editor.Fields["[MP3.Album]"].Text="Shared album";check(editor.List.Items.Cast<MediaEditorRow>().All(x=>x.Value("[MP3.Album]")=="Shared album"&&x.Dirty),"Editing a field updates all selected music drafts");editor.ConfirmForTests=n=>n==2;editor.SaveButton.RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));NavigationTests.Wait(editor.Work);foreach(string path in new[]{first,second})using(var file=TagLib.File.Create(path))check(file.Tag.Album=="Shared album","Editor saves shared album to "+Path.GetFileName(path));check(editor.List.Items.Cast<MediaEditorRow>().All(x=>!x.Dirty)&&Directory.GetFiles(root,"*.bak").Length>=2,"Editor refreshes saved drafts and keeps backups");editor.category.SelectedIndex=1;editor.UpdateLayout();check(editor.List.Items.Count==1&&editor.Fields["[Image.Author]"].Text=="Autor","Image category displays existing metadata");CheckLayout(editor,check,"Image");editor.Fields["[Image.Author]"].Text="New author";check(((MediaEditorRow)editor.List.Items[0]).Dirty,"Image edits remain a draft");NextStageTests.Draw(editor,Path.Combine(root,"metadata-editor.png"));editor.ConfirmForTests=n=>n==1;editor.SaveButton.RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));NavigationTests.Wait(editor.Work);using(var file=TagLib.File.Create(image))check(((TagLib.Image.CombinedImageTag)file.Tag).Creator=="New author","Editor saves image changes");
   editor.category.SelectedIndex=0;editor.List.SelectedIndex=0;editor.Fields["[MP3.Title]"].Text="Stale edit";File.AppendAllText(first,"external change");editor.SaveButton.RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));NavigationTests.Wait(editor.Work);var stale=(MediaEditorRow)editor.List.Items[0];check(stale.Error==L.Text("mediaNames.changed")&&stale.Dirty,"Editor blocks a draft when its source changes after loading");stale.Original=new Dictionary<string,string>(stale.Values);editor.Close();
  }
 }
}
#endif
